ProviderContainer _makeContainer({
  LocationService? locationService,
  SyncOrchestrator? syncOrchestrator,
  PhotoFiles? photoFiles,
}) {
  final db = AppDatabase(NativeDatabase.memory());
  final container = ProviderContainer(
